-- One row per nightly backup, written by deploy/backup-db.sh as the owner and read by the admin panel. Only what
-- the panel may show: the cause of a failure is a code, its details stay in the backup log. nearby_main gets access
-- through the default privileges of the database_roles migration.
CREATE TABLE "backup_runs" (
    "id" BIGSERIAL NOT NULL,
    "finished_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "succeeded" BOOLEAN NOT NULL,
    "attempts" INTEGER NOT NULL,
    "duration_seconds" INTEGER NOT NULL,
    "size_bytes" BIGINT,
    "reason" TEXT,

    CONSTRAINT "backup_runs_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "backup_runs_reason_check" CHECK (
        "reason" IN ('unreachable', 'auth_failed', 'timeout', 'locked', 'unreadable', 'failed')
    ),
    CONSTRAINT "backup_runs_outcome_check" CHECK (
        ("succeeded" AND "reason" IS NULL AND "size_bytes" IS NOT NULL)
        OR (NOT "succeeded" AND "reason" IS NOT NULL AND "size_bytes" IS NULL)
    )
);

CREATE INDEX "backup_runs_finished_at_idx" ON "backup_runs" ("finished_at");
